package fetvisuals.theme;
import java.util.*;
public final class ThemeManager {private final Map<String,Theme> themes=new LinkedHashMap<>();private Theme current;public ThemeManager(){register(new Theme("Fet Purple",0xFFB66DFF,0xFF6D38A6,0xF0080710,0xF0181422,0xFFEAE7F2,0xFFD78CFF));register(new Theme("Dark",0xFFB0B0B8,0xFF66666F,0xF0070709,0xF016161A,0xFFE6E6E8,0xFFAAAAAA));register(new Theme("Black",0xFFE0E0E0,0xFF555555,0xFF030303,0xFF0B0B0B,0xFFF4F4F4,0xFFD0D0D0));register(new Theme("Red",0xFFFF6B7A,0xFFA62E3C,0xF00D0608,0xF01F0D11,0xFFF0E7EA,0xFFFF7A8A));register(new Theme("Blue",0xFF73A9FF,0xFF3569B2,0xF0060A12,0xF00D1625,0xFFE7EEFA,0xFF78B0FF));register(new Theme("Green",0xFF71E6A1,0xFF2F9B62,0xF006100A,0xF00D2015,0xFFE7F6ED,0xFF79E7A7));current=themes.get("Fet Purple");}public void register(Theme t){themes.put(t.name(),t);}public Collection<Theme> all(){return themes.values();}public Theme current(){return current;}public void set(String name){if(themes.containsKey(name))current=themes.get(name);}}
